(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.015+t*0.15)*8 + Math.cos(my*0.02-t*0.1)*6;
  const w2y = Math.cos(mx*0.018-t*0.2)*8 + Math.sin(my*0.012+t*0.18)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.0],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.0],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.0],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5.0],
    [80+Math.sin(t*0.45+1.5)*70,40+Math.cos(t*0.65+2.5)*50,0.11,2.1,0.5],
    [400+Math.cos(t*0.55+3)*60,200+Math.sin(t*0.75+1)*55,0.085,2.4,3.5]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const ff=f*(1+0.2*Math.sin(t*0.3+ph));
    aS+=Math.sin(d*ff-t*sp+ph);
    iS+=Math.sin(d*ff*0.7+t*sp*0.6+1.5+ph*0.5);
    cS+=Math.cos(d*ff*0.5-t*sp*0.4+ph*0.8);
  }
  const act=aS/8,inh=iS/8,cross=cS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.06+sy*0.01-t*0.5)+Math.cos(sx*0.02+sy*0.05+t*0.6))/4+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.03-ang*2+t*0.8)*0.7+Math.sin(dist*0.06+ang*5-t*2)*0.5)*0.3;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2=Math.tanh((cross*0.5+act*inh*0.3-bg*0.4+spiral*0.5)*1.8);
  const reaction=Math.tanh((rd1+rd2*0.4)*1.5);
  const ci=Math.floor(sx*0.12),cj=Math.floor(sy*0.12),cp=t*0.15;
  let minD=999,minD2=999;
  for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
    const ni=ci+di,nj=cj+dj;
    const nx=ni*8.33+Math.sin(ni*1.7+nj*2.3+cp)*3.5;
    const ny=nj*8.33+Math.cos(ni*2.1+nj*1.3+cp*0.7)*3.5;
    const dd=Math.sqrt((sx-nx)**2+(sy-ny)**2);
    if(dd<minD){minD2=minD;minD=dd;}else if(dd<minD2)minD2=dd;
  }
  const cell=Math.tanh((minD2-minD)*0.8-0.3)*0.35;
  const breath=0.5+0.5*Math.sin(t*0.2);
  const blend=reaction*0.65+cell*0.2+spiral*0.1*breath+cross*0.05;
  const v=blend*0.5+0.5;
  const pal=[[12,22,72],[18,55,105],[22,95,125],[30,140,135],[55,170,120],[140,185,75],[210,185,60],[225,140,65],[210,95,70],[175,60,80],[120,40,90],[60,30,100],[12,22,72]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const vd=Math.sqrt((x-cx)**2+(y-cy)**2);
  const vig=1.0-vd*0.0004;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0];
}
